parameters.jsCode:
const req = $input.first().json;
const headers = req.headers || {};
const query = req.query || {};

const authHeader = headers.authorization || headers.Authorization || query.token || '';
let token = authHeader.replace(/^Bearer /i, '').trim();

if (!token) {
  return [{ json: { error: true, statusCode: 401, message: 'Unauthorized. Please login.' } }];
}

let decoded;
try {
  decoded = JSON.parse(Buffer.from(token, 'base64').toString('utf8'));
} catch(e) {
  return [{ json: { error: true, statusCode: 401, message: 'Invalid session.' } }];
}

if (!decoded || !decoded.userId || (decoded.exp && decoded.exp < Math.floor(Date.now() / 1000))) {
  return [{ json: { error: true, statusCode: 401, message: 'Session expired.' } }];
}

return [{
  json: {
    userId: decoded.userId,
    clientId: decoded.clientId,
    role: decoded.role,
    hospitalName: decoded.hospitalName
  }
}];

